{
  "findings": [
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "A parent can limit who their child interacts with via parental controls.",
      "stance": "mitigation",
      "quote": "Creating a child account is one of the best ways to make sure your kids have some built in protections to keep their experiences age-appropriate. Microsoft and Minecraft offer child accounts that empower parents to manage and monitor gameplay, multiplayer access, chat settings, and friend requests. This includes default features that limit the ability to interact with strangers."
    },
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "Voice chat is not available in the PC version of Minecraft.",
      "stance": "neutral",
      "quote": "Voice chat is not available in the PC version of the game, but players can use other platforms like Discord to chat while playing."
    },
    {
      "ref": "[D536]",
      "area": "contact",
      "claim": "Console versions of Minecraft have in-game voice chat.",
      "stance": "neutral",
      "quote": "Meanwhile, those playing on game console platforms, like Xbox and PlayStation, do have access to in-game voice chat."
    },
    {
      "ref": "[D536]",
      "area": "money",
      "claim": "Minecraft offers in-game purchases using Minecoins or Minecraft Tokens.",
      "stance": "risk",
      "quote": "Regardless of the version, Minecoins (Minecraft's in-game currency) can be used to purchase downloadable content in the Minecraft Marketplace. Note that these purchases are completely optional."
    },
